// This file is generated by AI.

// 全项目唯一的右键/下拉菜单。
//
// 为什么要有它: 这套菜单此前在五处各写了一遍 (文件树、文件树工具栏、仓库页、提交历史、
// 配音记录), 每处都自己复制一份"遮罩 + 定位 + 按钮"的 JSX 与样式。它们的差别只是
// 内容, 但样式一分叉就出事故 —— 配音记录那份把 `.context-menu` 的 `z-index` 从 2600
// 覆盖成了 2000, 而遮罩仍是 2500, 于是**遮罩盖在菜单上面**: 其余四处菜单里的按钮全都
// 点不动 (点到的其实是遮罩, 菜单只会被关掉), 配音记录自己反而正常 (它当时还没用遮罩)。
//
// 因此这里把结构定死:
// * 遮罩在菜单**下面** (z-index 2500 < 2600), 且覆盖整个视口, 点它/右键它即关闭;
// * 菜单 `position: fixed` 贴在指针处, 由组件自己按**实测尺寸**收回视口内
//   (以前各处用 `window.innerWidth - 200` 这类猜测值估算, 菜单一长就还是被裁掉);
// * `Esc` 与窗口尺寸变化都关闭;
// * 每一项都是同一个 `.context-menu-item` 按钮, 支持图标 / 危险色 / 禁用 / 悬浮说明。

import { useEffect, useLayoutEffect, useRef, type ReactNode } from 'react';

export interface ContextMenuItem {
  /** 唯一键 */
  key: string;
  label: ReactNode;
  icon?: ReactNode;
  /** 危险操作 (删除、放弃更改等), 用危险色 */
  danger?: boolean;
  disabled?: boolean;
  /** 悬浮说明 (原生 title) */
  title?: string;
  onClick: () => void;
}

interface Props {
  /** 指针位置 (菜单左上角的目标点) */
  x: number;
  y: number;
  items: ContextMenuItem[];
  onClose: () => void;
}

export function ContextMenu({ x, y, items, onClose }: Props) {
  const ref = useRef<HTMLDivElement>(null);

  /*
   * 贴边时按实际尺寸收回视口内。
   *
   * 直接改样式而不是存进 state: 菜单的位置只取决于"指针 + 自身尺寸", 走 state 就得在
   * layout effect 里 setState, 而 `items` 每次渲染都是新数组 —— 那会变成
   * "渲染 -> 测量 -> setState -> 渲染" 的死循环。写样式没有这个问题。
   * 放在 layout effect 里是为了在浏览器绘制之前纠正, 用户看不到中间态。
   */
  useLayoutEffect(() => {
    const node = ref.current;
    if (!node) return;
    const rect = node.getBoundingClientRect();
    node.style.left = `${Math.max(4, Math.min(x, window.innerWidth - rect.width - 4))}px`;
    node.style.top = `${Math.max(4, Math.min(y, window.innerHeight - rect.height - 4))}px`;
  }, [x, y, items]);

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('resize', onClose);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('resize', onClose);
    };
  }, [onClose]);

  return (
    <>
      <div
        className="context-menu-backdrop"
        onClick={onClose}
        onContextMenu={(event) => {
          // 在遮罩上再点右键: 关掉当前菜单, 而不是弹出浏览器的
          event.preventDefault();
          onClose();
        }}
      />
      <div ref={ref} className="context-menu" style={{ left: x, top: y }} role="menu">
        {items.map((item) => (
          <button
            key={item.key}
            type="button"
            role="menuitem"
            className={`context-menu-item${item.danger ? ' danger' : ''}`}
            disabled={item.disabled}
            title={item.title}
            onClick={() => {
              // 先关菜单再执行: 动作可能会打开对话框/改状态, 菜单不该留在上面
              onClose();
              item.onClick();
            }}
          >
            {item.icon}
            {item.label}
          </button>
        ))}
      </div>
    </>
  );
}
